-- EPUB batch 4: additive intake evidence, chunk staging and enquiry inbox.
-- Existing project/file tables are reused; all source files remain security-pending.

CREATE TABLE IF NOT EXISTS conversion_project_events (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,project_id CHAR(36) NOT NULL,revision INT UNSIGNED NOT NULL,event_type VARCHAR(48) NOT NULL,actor_id BIGINT UNSIGNED NOT NULL,detail_json JSON NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,KEY project_events(tenant_id,project_id,id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS conversion_source_inspections (tenant_id BIGINT UNSIGNED NOT NULL,project_id CHAR(36) NOT NULL,ordinal INT UNSIGNED NOT NULL,inspection_json JSON NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(tenant_id,project_id,ordinal)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS conversion_upload_rejections (tenant_id BIGINT UNSIGNED NOT NULL,id CHAR(36) NOT NULL,actor_id BIGINT UNSIGNED NULL,sha256 CHAR(64) NOT NULL,code VARCHAR(48) NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(tenant_id,id),KEY upload_rejections(tenant_id,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS conversion_projects (tenant_id BIGINT UNSIGNED NOT NULL,id CHAR(36) NOT NULL,service VARCHAR(32) NOT NULL DEFAULT 'epub',title VARCHAR(160) NOT NULL,created_by BIGINT UNSIGNED NOT NULL,idempotency_key VARCHAR(64) NOT NULL,fingerprint CHAR(64) NOT NULL,plan_json JSON NOT NULL,status VARCHAR(32) NOT NULL DEFAULT 'held',hold_reason VARCHAR(64) NOT NULL,revision INT UNSIGNED NOT NULL DEFAULT 1,rights_confirmed_at DATETIME NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(tenant_id,id),UNIQUE KEY conversion_intake_request(tenant_id,service,created_by,idempotency_key),KEY conversion_project_owner(tenant_id,created_by,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS conversion_project_assets (tenant_id BIGINT UNSIGNED NOT NULL,project_id CHAR(36) NOT NULL,ordinal INT UNSIGNED NOT NULL,file_id BIGINT UNSIGNED NOT NULL,sha256 CHAR(64) NOT NULL,source_kind VARCHAR(32) NOT NULL,PRIMARY KEY(tenant_id,project_id,ordinal),KEY conversion_asset_file(tenant_id,file_id),CONSTRAINT conversion_asset_project_fk FOREIGN KEY(tenant_id,project_id) REFERENCES conversion_projects(tenant_id,id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS conversion_upload_sessions (tenant_id BIGINT UNSIGNED NOT NULL,id CHAR(36) NOT NULL,owner_id BIGINT UNSIGNED NOT NULL,request_key VARCHAR(64) NOT NULL,token_hash CHAR(64) NOT NULL,filename VARCHAR(255) NOT NULL,total_size INT UNSIGNED NOT NULL,expected_sha256 CHAR(64) NOT NULL,status VARCHAR(16) NOT NULL DEFAULT 'open',inspection_json JSON NULL,project_id CHAR(36) NULL,plan_hash CHAR(64) NULL,expires_at DATETIME NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(tenant_id,id),KEY upload_owner(tenant_id,owner_id,expires_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS conversion_upload_chunks (tenant_id BIGINT UNSIGNED NOT NULL,session_id CHAR(36) NOT NULL,chunk_index INT UNSIGNED NOT NULL,sha256 CHAR(64) NOT NULL,size_bytes INT UNSIGNED NOT NULL,body MEDIUMBLOB NOT NULL,PRIMARY KEY(tenant_id,session_id,chunk_index)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS conversion_enquiries (tenant_id BIGINT UNSIGNED NOT NULL,id CHAR(36) NOT NULL,request_key VARCHAR(64) NOT NULL,name VARCHAR(100) NOT NULL,email VARCHAR(254) NOT NULL,message TEXT NOT NULL,status VARCHAR(16) NOT NULL DEFAULT 'new',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(tenant_id,id),UNIQUE KEY enquiry_request(tenant_id,request_key),KEY enquiry_inbox(tenant_id,status,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
